CREATE TABLE ACCOUNT (
    A_CODE VARCHAR2(30) NOT NULL,
    A_NAME VARCHAR2(100) NOT NULL,
    A_NAME_ENG VARCHAR2(100),
    A_LEVEL NUMBER(5) NOT NULL,
    A_PARENT VARCHAR2(30) NOT NULL,
    A_S_M NUMBER(5) NOT NULL,
    A_GROUPING NUMBER(5),
    A_REPORT NUMBER(5) NOT NULL,
    A_ANALYSIS NUMBER(10),
    CLASS_NO NUMBER(5),
    AC_CLOSE NUMBER(1) DEFAULT 0,
    DR NUMBER(1),
    CURDIF_CODE VARCHAR2(30),
    USE_CC NUMBER(1),
    USE_PJ NUMBER(1),
    CONN_PRD NUMBER(1) DEFAULT 0,
    FAV_AC NUMBER(1) DEFAULT 0,
    FLOW_TYPE NUMBER(1),
    INACTIVE_RES VARCHAR2(250),
    INACTIVE_DATE DATE,
    CONF_LAST_DATE DATE,
    AC_OP_NO NUMBER(15),
    AC_EXP_TYPE NUMBER(2),
    ADVNC_EXPNS_RVNU_FLG NUMBER(1) DEFAULT 0,
    USE_EXP_BRN NUMBER(1) DEFAULT 0 ,
    IMP_XLS NUMBER(1) DEFAULT 0,
    AC_DTL_TYP NUMBER(2) DEFAULT 0 ,
    USE_ACTV NUMBER(1),
    USE_TDS_FLG NUMBER(1) DEFAULT 0,
    USE_INSRT_TYP NUMBER(1) DEFAULT 0,
    AC_CODE_MNL VARCHAR2(30),
    AD_U_ID NUMBER(5),
    AD_DATE DATE,
    UP_U_ID NUMBER(5),
    UP_DATE DATE,
    UP_CNT NUMBER(10),
    PR_REP NUMBER(10),
    AD_TRMNL_NM VARCHAR2(50),
    UP_TRMNL_NM VARCHAR2(50),
    CONSTRAINT pk_ACCOUNT PRIMARY KEY (A_CODE)
);
ALTER TABLE ACCOUNT
ADD CONSTRAINT fk_ACCOUNT_ACCOUNT_TYPES FOREIGN KEY (A_S_M)
REFERENCES ACCOUNT_TYPES (ACCOUNT_TYPE);
ALTER TABLE ACCOUNT
ADD CONSTRAINT fk_ACCOUNT_IAS_ACCOUNT_CLASS FOREIGN KEY (CLASS_NO)
REFERENCES IAS_ACCOUNT_CLASS (CLASS_NO);
ALTER TABLE ACCOUNT
