REFERENCES ACCOUNT_GROUPING (GROUP_NO);
ALTER TABLE ACCOUNT
ADD CONSTRAINT fk_ACCOUNT_ACCOUNT_REPORT_TYPE FOREIGN KEY (A_REPORT)
REFERENCES ACCOUNT_REPORT_TYPE (REPORT_TYPE);

